    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我一点一点变轻了 像气球"
        },
        {
          "id": "V1-02",
          "zh": "你却把一切都夺走 不放手"
        },
        {
          "id": "V1-03",
          "zh": "不管什么都被吸进 你胸口"
        },
        {
          "id": "V1-04",
          "zh": "吞下去就消失无踪"
        },
        {
          "id": "V1-05",
          "zh": "我一点一点变弱了 像残风"
        },
        {
          "id": "V1-06",
          "zh": "心里那块黑色污渍 也都被"
        },
        {
          "id": "V1-07",
          "zh": "干干净净洗掉 不留痕迹"
        },
        {
          "id": "V1-08",
          "zh": "什么都不用做也可以"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我渐渐变得轻盈"
        },
        {
          "id": "V1-02",
          "zh": "你把一切都夺去"
        },
        {
          "id": "V1-03",
          "zh": "无论什么都能吸入"
        },
        {
          "id": "V1-04",
          "zh": "全都吞噬殆尽"
        },
        {
          "id": "V1-05",
          "zh": "我渐渐变得虚弱"
        },
        {
          "id": "V1-06",
          "zh": "心中的黑色污渍"
        },
        {
          "id": "V1-07",
          "zh": "也被彻底洗净"
        },
        {
          "id": "V1-08",
          "zh": "于是什么都不用做也好"
        }
      ]
    }
  ]
